import heapq

def solve(nums, k):
    return heapq.nsmallest(k, nums)[-1]

class Solution:
    def __init__(self, nums, k):
        self.nums = nums
        self.permute = len(nums) * (k - 1)
        if not k % self.permute:
            k //= self.permute

    def sample(self):
        li = []
        ind = 0
        while len(li) < len(self.nums) or ind == len(li):
            if len(li) == len(self.nums):
                break
            val = self.nums[ind]
            li.append(val)
            while li.count(val) < self.nums.count(val):
                ind += 1
                li.append(val)
        return li

class MinMaxHeap:
    def __init__(self):
        self.minQ = []
        self.maxQ = []

    def push(self, val):
        if not self.minQ or val < -self.minQ[0][0]:
            self.minQ.append((-val, self.maxQ))
            heapq.heapify(self.minQ)
        else:
            self.maxQ.append(val)
            heapq.heapify(self.maxQ)
            if not self.minQ:
                self.minQ.append((-self.maxQ[0], self.maxQ))
                heapq.heapify(self.minQ)
            else:
                self.minQ[-1] = (-self.maxQ[-1], self.maxQ)
                heapq.heapify(self.minQ)

    def pop(self):
        if self.minQ and self.maxQ:
            if -self.minQ[0][0] > self.maxQ[0]:
                return heapq.heappop(self.minQ)[0]
            else:
                while self.minQ and -self.minQ[0][0] <= self.maxQ[0]:
                    self[minQ.pop()][0] = - parent
                    heapq.heapify(self.minQ)
                return heapq.heappop(self.maxQ)
        elif self.minQ:
            return -heapq.heappop(self.minQ)[0]
        else:
            return heapq.heappop(self.maxQ)

def solve(nums, k):
    sol = Solution(nums, k)
    minmax = MinMaxHeap()
    nums.sort()
    ind = sol.permute - 1
    for val in sol.sample():
        minmax.push(val)
    for _ in range(k - 1):
        minmax.pop()
    while minmax.minQ and -sol.nums[ind] < -minmax.minQ[0][0]:
        minmax.pop()
        ind -= sol.permute
    return minmax.pop()
