import bisect

def solve(nums, k):
    return sorted(nums)[k-1]

class NumArray:
    def __init__(self, nums):
        self.BUCKET_SIZE = 10**4
        self.min_bucket = [[] for _ in range(self.BUCKET_SIZE + 1)]
        self.max_bucket = [[] for _ in range(self.BUCKET_SIZE + 1)]
        self.all_nums = set()
        self.bisect_orders = {}

        for i, num in enumerate(nums):
            if num not in self.all_nums:
                self.all_nums.add(num)
                bisect_order = bisect.bisect_left(sorted(nums), num)
                self.bisect_orders[num] = bisect_order

            self.min_bucket[bisect.bisect_left(nums, num)].append((num, i))
            self.max_bucket[self.BUCKET_SIZE - bisect.bisect_left(nums, num)].append((num, i))

    def add(self, idx, val):
        if val in self.all_nums:
            bisect_order = self.bisect_orders[val]
        else:
            self.all_nums.add(val)
            bisect_order = bisect.bisect_left(sorted(self.all_nums), val)

        self.min_bucket[bisect_order].remove((val, idx))
        self.max_bucket[self.BUCKET_SIZE - bisect_order].remove((val, idx))

        self.min_bucket[bisect_order].append((val, idx))
        self.max_bucket[self.BUCKET_SIZE - bisect_order].append((val, idx))
        self.bisect_orders[val] = bisect_order

    def update(self, idx, val):
        self.add(idx, val)

    def find(self, k):
        bucket = 0
        while bucket <= self.BUCKET_SIZE and len(self.min_bucket[bucket]) < k:
            bucket += 1

        return sorted([num for num, idx in self.min_bucket[bucket]])[k-1]
