import heapq

def solve(nums, k):
    count = {}
    for num in nums:
        count[num] = count.get(num, 0) + 1

    heaps = [[weight, val] for val, weight in count.items()]
    heapq.heapify(heaps)

    for _ in range(k - 1):
        weight, val = heapq.heappop(heaps)
        if weight > 1:
            heapq.heappush(heaps, [weight - 1, val])

