import random
import heapq

def solve(nums, k):
    def swap(i, j):
        nums[i], nums[j] = nums[j], nums[i]

    def partition(l, r):
        pivot_index = random.randint(l, r)
        swap(l, pivot_index)
        i = l + 1
        for j in range(l + 1, r):
            if nums[j] < nums[l]:
                swap(i, j)
                i += 1
        swap(l, i - 1)
        return i - 1

    def quickselect(left, right, k):
        if left == right:
            return nums[left]
        pivot_index = partition(left, right)
        if k == pivot_index + 1:
            return nums[pivot_index]
        elif k < pivot_index + 1:
            return quickselect(left, pivot_index - 1, k)
        else:
            return quickselect(pivot_index + 1, right, k)

    return quickselect(0, len(nums) - 1, k)

def heapify_max(nums, k):
    heap = nums[:k]
    heapq.heapify(heap)
    for num in nums[k:]:
        if num > heap[0]:
            heapq.heappop(heap)
            heapq.heappush(heap, num)
    return heap[0]

