from functools import lru_cache

@lru_cache(None)
def factorials(n):
    if n == 0:
        return 1
    return n * factorials(n - 1)

def solve(nums, k):
    n = len(nums)
    counts = {}
    for num in nums:
        if num not in counts:
            counts[num] = 0
        counts[num] += 1

    frac_heap = []
    total = 0
    for num, count in sorted(counts.items()):
        fraction = n - total - count + 1
        d = count
        while d >= fraction:
            heapq.heappush(frac_heap, (-factorials(d - fraction + 1) // (d - fraction + 1) * fraction, num))
            d -= 1
        total += count
        if len(frac_heap) >= k:
            return -heapq.heappop(frac_heap)[1]
    return None
