import bisect

def solve(nums, k):
    nums = sorted(set(nums))
    if k > len(nums):
        raise ValueError("k is larger than the length of the list")
    return nums[bisect.bisect_left(nums, nums[k-1]) - 1]

def bisect_left(a, x, lo=0, hi=None):
    if lo < 0:
        raise ValueError("lo must be non-negative")
    if hi is None:
        hi = len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if x < a[mid]:
            hi = mid
        else:
            lo = mid + 1
    return lo
