import random

def get_randomized_sampling(nums):
    return sorted(random.sample(nums, min(random.randint(1, len(nums)), 100)))  # limit cart to 100 for performance

def partialQuickSelect(nums, k, low, high, result = []):
    if low == high == 0:
        return partialQuickSelect(nums, k, 1, len(nums)-1, result)

    random_index = random.randint(low, high)
    nums[low], nums[random_index] = nums[random_index], nums[low]

    pivot_index = get_pivot_index(nums, low, high, nums[low])
    nums[pivot_index], nums[low] = nums[low], nums[pivot_index]

    if k <= pivot_index+1:
        return partialQuickSelect(nums, k, low, pivot_index-1, result)
    elif k > len(result) + (pivot_index - low) + 1:
        return partialQuickSelect(nums, k, pivot_index+1, high, result + nums[low:pivot_index+1])
    else:
        result.extend(nums[low:pivot_index+1])
        return result

def get_pivot_index(nums, low, high, pivot):
    less = greater = i = low
    while i <= high:
        if nums[i] < pivot:
            nums[i], nums[less] = nums[less], nums[i]
            less += 1
        elif nums[i] > pivot:
            nums[i], nums[greater] = nums[greater], nums[i]
            less += 1
            greater += 1
            nums[i], nums[greater-1] = nums[greater-1], nums[i]
        i += 1
    nums[:greater] = sorted(nums[:greater])
    return greater - 1

def solve(nums, k):
    k -= 1
    result = partialQuickSelect(nums, k, 0, len(nums)-1, [])
    return result[k] if k < len(nums) else None
