            else:
                if prefix:
                    prefix = prefix_suffix_match[prefix - 1]
                    while prefix and haystack[i] != needle[prefix]:
                        prefix = prefix_suffix_match[prefix - 1]
                else:
                    i += 1
        return -1
    return KMP_search(haystack, needle)
