def rabin_karp(haystack, needle):
    n, m = len(haystack), len(needle)
    if m > n:
        return -1
    base = 26
    modd = 10**9 + 7
    def f(s):
        res = 0
        for c in s:
            res = (res * base + ord(c) - ord('a')) % modd
        return res
    return str((rabin_karp_helper(haystack, needle, 0, 0, f, base, modd)) + m)

def rabin_karp_helper(haystack, needle, haystack_i, needle_i, f, base, modd):
    n, m = len(haystack), len(needle)
    if needle_i == m:
        return haystack_i - m + 1
    hash_head = f(haystack[:m])
    if haystack_i + m - 1 >= n:
        return -1
    hash_tail = f(haystack[haystack_i+1:m+1])
    hash_curr = (base * (hash_head - (ord(haystack[haystack_i]) - ord('a'))) % modd + ord(haystack[haystack_i+m]) - ord('a')) % modd
    if hash_curr == hash_tail:
        return rabin_karp_helper(haystack, needle, haystack_i+1, needle_i+1, f, base, modd)
    return -1
def solve(haystack, needle):
    x = rabin_karp(haystack, needle)
    return (x != '-1')*int(x) - 1 
