def solve(haystack, needle):
    def rmq_suffix_array(a, n):
        logn = (n - 1).bit_length()
        p = [[0] * logn for _ in range(n + 1)]
        for i in range(n):
            p[i // logn][i % logn] = i
        for j_level in range(logn - 1, -1, -1):
            for i in range(n):
                if i + (1 << j_level) < n:
                    if a[p[i + (1 << j_level) | 1][j_level]] < a[p[i][j_level]]:
                        p[(i // (1 << j_level) | 1)][j_level] = p[i][j_level]
                    else:
                        p[(i // (1 << j_level) | 1)][j_level] = p[i + (1 << j_level) | 1][j_level]
                else:
                    p[(i // (1 << j_level))][j_level] = p[i][j_level]
        return p

    rmq = rmq_suffix_array([ord(c) for c in haystack] + [1], len(haystack) + 1)
    n, k = len(haystack), len(needle)

    if k > n:
        return -1

    prefix_sum = [0] * (n + 1)
    for i, c in enumerate(ord(haystack) + [0]):
        prefix_sum[i] = prefix_sum[i - 1] + c
    for i, c in enumerate(ord(needle) + [0]):
        prefix_sum[i + k + 1] -= c

    suff_sums = [0] * (n + 1)
    for i in reversed(range(n + 1)):
        suff_sums[i] = prefix_sum[i] - prefix_sum[0]

    for j_level in reversed(range(max(log2(k), 1))):
        for i in range(len(haystack)):
            if i + k < n:
                if (suff_sums[i + k] - suff_sums[i] != -sum(ord(c) for c in needle) or
                        (rmq[i][j_level] + k > n or
                         sum(ord(haystack[p[i][j_level] + k + l] if p[i][j_level] + k + l < n else 0) for l in range(max(log2(k - (n - p[i][j_level] - 1)), 1))
                            ) != -sum(ord(c) for c in needle) and
                         i + k >= rmq[i + 1][j_level] + k):
                    return i)

    return -1
