def hash(x):
    hash = 0
    for b in [x & 0xf, (x >> 4) & 0xf, (x >> 8) & 0xf, (x >> 12) & 0xf]:
        hash = ((hash << 5) - hash) + b
        hash |= 0x7f
        hash ^= hash >> 16
        hash &= 0xffffffff
        hash *= 0x1505
        hash &= 0xffffffff
    return hash

class NumHash:
    def __init__(self, nums):
        self.group = {}

        prefix = 0
        prefix_hashes = []
        for num in nums:
            prefix_hashes.append(hash(prefix))
            prefix = (hash(num) + prefix * 0x1505) & 0xffffffff
            prefix_hashes.append(hash(prefix))

        self.prefix_hashes = prefix_hashes

        for num in nums:
            compressor = 0
            for offset, hash in enumerate(self.prefix_hashes):
                compressor += hash * pow(2, 31, 2**32 - 1) ** offset
                compressor &= 0xffffffff
            self.group.setdefault(compressor, []).append(num)

    def search(self, target):
        prefix = 0
        full_hashes = []
        prefix_hashes = []
        compressor = 0
        for num in self.group:
            prefix_compress = prefix * 0x1505 & 0xffffffff
            prefix += hash(num) & 0xffffffff
            full_hashes.append((hash(num), compressor))
            prefix_hashes.append(hash(prefix_compress))
            compressor += hash(num) * pow(2, 31, 2**32 - 1) ** len(full_hashes)
            compressor &= 0xffffffff
            if compressor == self.target - target:
                return full_hashes, prefix_hashes
            elif compressor > self.target - target:
                break
        return full_hashes, prefix_hashes
