        nums.sort()
        left, right = 0, len(nums) - 1
        result = float('inf')
        pair = ()
        while left < right:
            current_sum = nums[left] + nums[right]
            current_diff = abs(current_sum - target)
            if current_diff < result:
                result = current_diff
                pair = (nums[left], nums[right])
            if current_sum < target:
                left += 1
            else:
                right -= 1
        return pair

