def solve(n, edges):
    dsu = DSU(n)
    for u, v in edges:
        dsu.unify(u, v)
    return n - dsu.getCountByCount()

class DSU:
    def __init__(self, n):
        self.group = list(range(n))
        self.e_count = list(range(n))
        self.e_by_count = {1: 0}

    def unify(self, x, y):
        x_root = self.find(x)
        y_root = self.find(y)

        if x_root == y_root: return

        e_count = self.getEdgeCount(x)
        self.e_count[x_root] += self.e_count[y_root]
        self.e_by_count[e_count] -= 1
        if self.e_count[x_root] in self.e_by_count: self.e_by_count[self.e_count[x_root]] = 0
        if self.e_count[x_root] + 1 not in self.e_by_count: self.e_by_count[self.e_count[x_root] + 1] = 0
        self.e_by_count[self.e_count[x_root] + 1] += 1
        self.group[y_root] = x_root

    def find(self, u):
        while self.group[u] != u:
            self.group[u] = self.group[self.group[u]]
            u = self.group[u]
        return u

    def getEdgeCount(self, u):
        return u

    def getCountByCount(self):
        return sum(e_count * e_by_count for e_count, e_by_count in self.e_by_count.items())
