def solve(intervals):
    start_ends = sorted([(start, 0) for start, _ in intervals] + [(end, 1) for _, end in intervals], key=lambda x: (x[0], x[1]))
    interval_counts = [0]
    for _, end_type in start_ends:
        if end_type == 0:
            interval_counts.append(interval_counts[-1] + 1)
        else:
            interval_counts.append(interval_counts[-1] - 1)
    size = len(interval_counts)
    dp = [[0] * size for _ in range(size)]
    for gap in range(size):
        for i in range(size - gap):
            left, right = i, i + gap
            dp[left][right] = interval_counts[right] - interval_counts[left]
            for k in range(left, right):
                dp[left][right] = min(dp[left][k] + dp[k + 1][right], dp[left][right])
    return dp[0][-1]
