def solve(intervals):
    def get_end_non_overlapping(intervals):
        ends = sorted([i[1] for i in intervals])
        count = 0
        prev_end = float('-inf')
        for end in ends:
            if end > prev_end:
                count += 1
                prev_end = end
        return count

    def find_non_overlapping(intervals, avail_start):
        n = len(intervals)
        ends = [interval[1] for interval in intervals]
        dp = [[float('inf')] * (avail_start + 1) for _ in range(n + 1)]

        for i in range(n + 1):
            dp[i][0] = 0

        for i in range(1, n + 1):
            for j in range(1, avail_start + 1):
                if ends[i-1] <= j:
                    dp[i][j] = min(dp[i][j], dp[i-1][j])
                dp[i][j] = min(dp[i][j], dp[i-1][j-ends[i-1]] + 1)
        return dp[n][avail_start]

    def count_picking(intervals):
        return sum(find_non_overlapping(intervals, interval[0]) for interval in intervals)

    n = len(intervals)
    not_picked_count = get_end_non_overlapping(intervals)
    picked_count = count_picking(intervals)
    return not_picked_count + picked_count - n
