from typing import List

def solve(intervals: List[List[int]]) -> int:
    def graham_hull(points: List[int]) -> List[List[int]]:
        n = len(points)
        hull = []
        l = 0
        while True:
            hull.append(points[l])
            k = (l + 1) % n
            for i in range(n):
                if not ccw(hull[-2], hull[-1], points[i]):
                    k = i
            if k == l:
                break
            l = k
        return hull

    def ccw(a: int, b: int, c: int) -> bool:
        if a[0] > b[0]:
            a, b = b, a
        if c[0] > b[0]:
            b, c = c, b
        return (a[1] > b[1]) != (c[1] > b[1])

    points = [(interval[0], -interval[1], i) for i, interval in enumerate(intervals)]
    points.sort()
    low = [intervals[i][0] for k, i in sorted(range(len(intervals)), key=lambda i: points[i][0])]
    k = graham_hull(low)
    res = grammar_selection(k)
    return sum(res) * 2

def grammar_selection(hull: List[int]) -> List[int]:
    n = len(hull)
    Grammar_tree = [[0 for _ in range(n+1)] for _ in range(n)]
    dp = [[float('inf')] * (n + 1) for _ in range(n)]
    dp[0][0] = 0
    Grammar_tree[0][0] = 0
    for i in range(1, n+1):
        for j in range(i):
            if dp[j][i-1] + 2 < dp[i][i]:
                dp[i][i] = dp[j][i-1] + 2
                Grammar_tree[i][i] = j
            for k in range(j, i-1):
                if dp[j][k] + dp[k+1][i] < dp[j][i]:
                    dp[j][i] = dp[j][k] + dp[k+1][i]
                    Grammar_tree[j][i] = k
    return Grammar_tree

