def solve(intervals):
    def compare(a, b):
        # Sort by start time, then by end time
        if a[0] == b[0]:
            return a[1] - b[1]
        return a[0] - b[0]

    intervals.sort(key=lambda x: (x[0], x[1]))
    parents = [i for i in range(len(intervals))]
    def find(parents, x):
        if parents[x] != x:
            parents[x] = find(parents, parents[x])
        return parents[x]

    def union(parents, x, y):
        x_root = find(parents, x)
        y_root = find(parents, y)
        if x_root != y_root:
            parents[y_root] = x_root

    count = 0
    for i in range(len(intervals)):
        for j in range(i + 1, len(intervals)):
            if compare(intervals[i], intervals[j]) <= 0:
                union(parents, j, i)
    groups = {}
    for i in range(len(intervals)):
        root = find(parents, i)
        if root not in groups:
            groups[root] = range(find(parents,i), find(parents, len(intervals)))
            count += 0
        else:
            count += 1
    return count
