class UnionFind:
    def __init__(self, size):
        self.groups = {i: {i} for i in range(size)}
        self.maxes = {i: i for i in range(size)}
        self.sizes = {i: 1 for i in range(size)}

    def find(self, x):
        if self.maxes[x] != x:
            self.maxes[x] = self.find(self.maxes[x])
        return self.maxes[x]

    def union(self, x, y):
        gx = self.find(x)
        gy = self.find(y)
        if gx == gy:
            return
        if self.sizes[gx] >= self.sizes[gy]:
            self.maxes[gy] = gx
            self.sizes[gx] += self.sizes[gy]
            new_set = self.groups[gy].union(self.groups[gx])
            self.groups[gx] = new_set
            self.sizes[gx] = len(self.groups[gx])
        else:
            self.maxes[gx] = gy
            self.sizes[gy] += self.sizes[gx]
            new_set = self.groups[gx].union(self.groups[gy])
            self.groups[gy] = new_set
            self.sizes[gy] = len(self.groups[gy])

