        if n == 1:
            return 1
        power_matrix = self.matrix_power(n - 1)
        fib_result = [1, 1]
        for i in range(2, n + 1):
            fib_result = [x + y for x, y in zip(self.multiply(fib_result, power_matrix), fib_result)]
