from typing import List

def solve(n: int, prerequisites: List[List[int]]) -> List[int]:
    def build_graph(n: int, prerequisites: List[List[int]]) -> (List[List[int]], List[int]):
        create_edge = lambda x: {child: set() for child in range(n)}
        graph = [create_edge(i) for i in range(n)]

        for a, b in prerequisites:
            graph[b][a].add(b)
        return graph, n * [0]

    def has_cycle(graph: List[List[int]]) -> bool:
        def recursive_visit(node: int, visited: List[int], stack: List[int]) -> bool:
            if node in stack:
                return True
            if visited[node] == 1:
                return False
            visited[node] = 1
            stack.append(node)
            for child in graph[node]:
                if child in stack and child != node - 1:
                    return True
                for n in graph[child][node]:
                    if recursive_visit(n, visited, stack):
                        return True
            stack.pop()
            visited[node] = 2
            return False
        visited = n * [0]
        for i in range(n):
            if i not in visited or visited[i] == 1:
                if recursive_visit(i, visited, []) == True:
                    return True
        return False

    def topological_sort(graph: List[List[int]]) -> List[int]:
        topo = n * [0]
        in_degree = n * [0]

        for group in graph:
            for child in group:
                for node in group[child]:
                    in_degree[node] += 1
        ans = []
        inp_q = [i for i in range(n) if in_degree[i] == 0]

        while inp_q:
            t = inp_q.pop(0)
            ans.append(t)
            for node in graph[t]:
                in_degree[node] -= 1
                if in_degree[node] == 0:
                    inp_q.append(node)
        if len(ans) != n:
            return []
        return ans
    graph, in_degree = build_graph(n, prerequisites)
    if has_cycle(graph):
        return []
    return topological_sort(graph)
