    if node in current_path:
        return True
    if node in visited:
        return False
    visited.add(node)
    current_path.add(node)
    for neighbor in graph[node]:
        if dag_helper(graph, neighbor, visited, current_path):
            return True
    current_path.remove(node)
    return False

