def overlap_merge(intervals):
    def merge(left, right):
        if not left or not right:
            return left + right
        if left[1] >= right[0]:
            return [left[0], max(left[1], right[1])] + merge(left[1:] + right[1:], right[0 + 1:])
        return left + merge(right, right[0 + 1:])

    def sort_intervals(intervals):
        for i in range(len(intervals)):
            for j in range(len(intervals)):
                if intervals[i][0] < intervals[j][0]:
                    intervals[i], intervals[j] = intervals[j], intervals[i]
        return intervals

    def optimal_merge(intervals):
        if not intervals:
            return []
        if len(intervals) == 1:
            return intervals
        mid = (len(intervals) - 1) // 2
        left = optimal_merge(intervals[:mid + 1])
        right = optimal_merge(intervals[mid + 1:])
        return merge(sort_intervals(left), sort_intervals(right))

    return sort_intervals(optimal_merge(intervals))
