def heappop(h):
    return _heapify(h)[0]

def _sift_up(h, i):
    while i > 0:
        j = (i-1)//2
        if h[j][0] <= h[i][0]:
            break
        h[j], h[i] = h[i], h[j]
        i = j
    return h

def _heapify(h):
    heap = []
    while h:
        heap.append(heappop(h))
        _sift_up(h, len(heap)-1)
    return heap
