        if not left or not right:
            return left or right
        (start1, end1) = left[0]
        (start2, end2) = right[0]
        ret = []
        ret.append([min(start1, start2), max(end1, end2)])
        ret.extend(left[1:])
        ret.extend(right[1:])
        return ret

    def sort_intervals(intervals):
        return sorted(intervals, key=lambda x: x[0])

    def has_overlapping_intervals(intervals):
        for i in range(len(intervals) - 1):
            (start1, end1) = intervals[i]
            (start2, end2) = intervals[i + 1]
            if start2 <= end1:
                return True
        return False

    intervals = sort_intervals(intervals)
    sentinel = [[-1, -1]]
    while has_overlapping_intervals(intervals) and len(intervals) > 1:
        intervals = merge_intervals(intervals, sentinel)
    return intervals
