def solve(nums, target):
    def first_occurrence(nums, target):
        """Return the first index of target in nums"""
        left, right = 0, len(nums) - 1
        while left <= right:
            mid = left + (right - left) // 2
            if nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
