def insert(node, key):
    if not node:
        return {'val': key, 'left': None, 'right': None}
    if key == node['val']:
        node['count'] += 1
    elif key < node['val']:
        node['left'] = insert(node['left'], key)
    else:
        node['right'] = insert(node['right'], key)
    return node

def get_height(node):
    if not node:
        return -1
    return 1 + max(get_height(node['left']), get_height(node['right']))

def postorder(node):
    if not node:
        return []
    return postorder(node['left']) + postorder(node['right']) + [node['val']]

def solve(nums, k):
    freq = {}
    for num in nums:
        freq[num] = freq.get(num, 0) + 1
    sorted_nums = sorted(freq.items(), key=lambda x: (-x[1], x[0]))
    heap = []
    for num, count in sorted_nums:
        node = {'val': num, 'left': None, 'right': None, 'count': count}
        insert(node, num)
        heap.append(node)
        while len(heap) > k:
            node = heap.pop(0)
            if node['left']:
                insert(heap[-1], node['left']['val'])
                insert(heap[-1], node['right']['val'])
                node['left'] = node['right'] = None
    keys = []
    for node in heap:
        keys.extend(postorder(node))
    return keys[:k]
