import heapq

def nlargest2(n, nums, key=None):
    d = Counter(nums)
    return [num for num, count in heapq.nlargest(n, ((v, k) for k, v in d.items()), key=lambda x: x[1])]

def nlargest_key(n, nums, key, f=None):
    q = []
    for x in nums:
        heap = key(x, heap=q)
    return [x for x in heapq.nlargest(n, freq, key=f) if f == freq.get]

def heapify_keys(nums, key, heapfunc = (lambda a,b : a<b)):
    a = heapfunc(key([]),key([nums[0]]))
    heapq.heapify(key=[nums[0]])
    for s in nums[1:]:
        a = heapfunc(key[0], key=[s])
        if a:
            key[0] = s
            heapq.heappop(key)
            heapq.heappush(key, s)
    return key
