def solve(nums):
    def is_increase(it, n):
        for el in it:
            if el <= n:
                break
        else:
            return True
        return False

    # Phase 1: Count dp_{3} and the value forming it
    assert len(nums) >= 1
    dp1, val1 = [[a] for a in nums], nums[:]

    for i in range(1, len(nums)):
        for j in range(i):
            # if nums[i] is greater than nums[j], and nums[j] is already part of dp, then either it could be part of dp w/o nums[i] (this doesn't change the length,
            # but it makes the subsequence smaller), or it could be part of dp w/ nums[i] in which case the length increases by 1
            if nums[i] > nums[j]:
                val, ind = nums[i], i
                while ind >= 1 and (dp1[ind-1] == dp1[ind] or val > dp1[ind-1][-1]):
                    ind -= 1
                    val = dp1[ind][-1]
                if is_increase(dp1[ind], val):
                    val1[ind] = val
                    if is_increase(dp1[i], ind):
                        dp1[i] += [val]
                    else:
                        dp1[ind] += dp1[i]

    # Phase 2: Count dp_{2}
    dp2, val2 = [], nums[:]
    for i in range(len(nums)):
        length1 = len(dp1[i])
        len_prev, ind = -1, 0
        for j in range(i, len(nums)):
            if dp2:
                val, ind = dp2[ind]
            else:
                val, ind = -1, 0
            if nums[j] > val:
                dp2 = pd2 = list(zip(dp1[j:], nums[j:]))
                dp2.sort(key=lambda it: it[0][-1])
                val, ind = pd2[min(len_prev, length1)][0], min(length1, len_prev)
                makeMove = (length1 > len_prev)
            dp1[i].extend([nums[j]])
            if nums[j] > val:
                dp2.append((dp1[j], ind))
                dp2.sort(key=lambda it: it[0][-1])
                val2[ind] = nums[j]
                ind = (ind+1) % len(dp2)
                length_prev = dp1[i].count(nums[j-1]) * max(0 if len_prev == -1 else is_increase(dp2[0][0],val2[len_prev]) - 1, 0)
                len_prev = max(length1, length_prev)
                if length1 > len_prev or is_increase(pd2[0][0],val2[length1]):
                    pd2, val2, ind, length_prev = [], [], ind, max(length1,length_prev)
            else:
                makeMove = True

            if makeMove:
                dp1[i] = [min(el for el in dp1[i] if el <= nums[j])]
            length1 = len(dp1[i])

    max_len = len(nums)
    for length1, length2 in [(len(dp1[i]), len(dp2[ind])) for i in range(len(nums)) for ind in range(2**len(dp1[i]) - 1)]:
        max_len = max(length1+length2, max_len)

    return max_len
