def solve(nums):
    def longest_increasing_subsequence(i, dp):
        if i < 0:
            return 0
        if dp[i] != -1:
            return dp[i]
        dp[i] = 1 + max(longest_increasing_subsequence(i-1, dp), longest_increasing_subsequence(find_prev_index(i, nums, dp), dp))
        return dp[i]

    def find_prev_index(i, nums, dp):
        j = i - 1
        while j >= 0 and nums[j] >= nums[i]:
            j = longest_increasing_subsequence(j, dp) - 1
        return j

    dp = [-1] * len(nums)
    return longest_increasing_subsequence(len(nums)-1, dp)
