def solve(nums):
    n = len(nums)
    if n == 0:
        return 0

    lookup = [nums[0]]

    for i in range(1, n):
        if nums[i] < lookup[-1]:
            lookup.append(nums[i])
        else:
            idx = binary_search(lookup, nums[i])
            lookup[idx] = nums[i]

    return len(lookup)

def binary_search(arr, target):
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return left
