        dp[0] = nums[0]
        for i in range(1, len(nums)):
            prev_max = 0
            for j in range(i):
                if nums[i] > nums[j] and dp[j] > prev_max:
                    prev_max = dp[j]
            dp[i] = max(prev_max + 1, dp[i - 1])
        return max(dp)

    len_nums = len(nums)
    if len_nums == 0:
        return 0
    dp = [0] * len_nums
    return longest_increasing_subsequence(nums, dp)
